    int maxCount = 1;

    for (int i = 0; i < pointsSize; i++) {
        // Map from slope to count
        // Use a hash map with open addressing or chaining
        // Since pointsSize <= 300, max slopes per point <= 299
        // We'll implement a simple hashmap with linear probing

        // Key: slope represented as pair (num, den)
        // Value: count

        // We'll store keys and counts in arrays
        // Max size 600 (to reduce collisions)
        int capacity = 600;
        Slope *keys = (Slope*)calloc(capacity, sizeof(Slope));
        int *counts = (int*)calloc(capacity, sizeof(int));
        int *used = (int*)calloc(capacity, sizeof(int));

        int samePointCount = 0; // not needed since points are unique

        int localMax = 0;

        for (int j = i + 1; j < pointsSize; j++) {
            int dx = points[j][0] - points[i][0];
            int dy = points[j][1] - points[i][1];

            if (dx == 0 && dy == 0) {
                // same point, but problem states unique points, so ignore
                samePointCount++;
                continue;
            }

            // Normalize slope
            int g = gcd(dy, dx);
            if (g != 0) {
                dy /= g;
                dx /= g;
            }

            // Keep denominator positive for uniqueness
            if (dx < 0) {
                dx = -dx;
                dy = -dy;
            } else if (dx == 0 && dy < 0) {
                // vertical line slope is (1,0)
                dy = -dy;
            }

            // Insert into hashmap
            // Linear probing
            int hash = ((dy * 100000 + dx) & 0x7fffffff) % capacity;
            while (used[hash]) {
                if (keys[hash].num == dy && keys[hash].den == dx) {
                    counts[hash]++;
                    break;
                }
                hash = (hash + 1) % capacity;
            }
            if (!used[hash]) {
                used[hash] = 1;
                keys[hash].num = dy;
                keys[hash].den = dx;
                counts[hash] = 1;
            }
            if (counts[hash] > localMax) localMax = counts[hash];
        }

        free(keys);
        free(counts);
        free(used);

        if (localMax + 1 > maxCount) maxCount = localMax + 1;
    }

    return maxCount;
}

